INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES
  ('b7e4c91a2d6f40c8a35e79b1f24d68ab', NULL, '8f3c2a1e7b654d0ba92e31c4f68add5a', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The page collects course experiments, thesis progress, graduation procedures, and 2025 archived records, and the most recent directory organization took place on May 1.", "link": null}, "plain_text": "The page collects course experiments, thesis progress, graduation procedures, and 2025 archived records, and the most recent directory organization took place on May 1."}]}', 0, 0, 0, '2026-05-01T08:00:00.000Z', '2026-05-01T08:20:00.000Z'),
  ('b07d1639c4e74682ad3f951e605a2871', NULL, '4d3a6e90b8c84fe7a97f3d1c2b760145', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "Last year''s records include three directions: databases, cloud platforms, and compilers. Each entry only retains the city and the last update time; the page was archived on November 30, 2025.", "link": null}, "plain_text": "Last year''s records include three directions: databases, cloud platforms, and compilers. Each entry only retains the city and the last update time; the page was archived on November 30, 2025."}]}', 0, 0, 1, '2025-11-30T08:05:00.000Z', '2025-11-30T10:20:00.000Z'),
  ('0a6f58dce9b74673ac1e250f8d943b62', NULL, '97ab5d1f2c304f9a8e671bd042ce5938', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The 2025 payment records include a 8000 yuan university scholarship, two research assistant stipends, and one conference travel reimbursement; the travel funds do not count as personal income.", "link": null}, "plain_text": "The 2025 payment records include a 8000 yuan university scholarship, two research assistant stipends, and one conference travel reimbursement; the travel funds do not count as personal income."}]}', 0, 0, 2, '2025-12-18T03:45:00.000Z', '2025-12-18T04:05:00.000Z'),
  ('f1c83d7062a54be9b4d219a37e6805ca', NULL, 'c28f6b73a9144e5db6017f8a39ce205d', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The student office collected a paper enrollment certificate in October 2025, and the college finance office retained a scanned copy of the travel reimbursement form; the two materials belong to different handling processes.", "link": null}, "plain_text": "The student office collected a paper enrollment certificate in October 2025, and the college finance office retained a scanned copy of the travel reimbursement form; the two materials belong to different handling processes."}]}', 0, 0, 3, '2025-10-09T06:15:00.000Z', '2025-10-12T09:30:00.000Z'),
  ('block_notion_research_log', NULL, 'notion_research_log', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The reading page already has four sets of public material links for PagedAttention, continuous batching, KV cache, and GPU profiling, and two of the articles include reproduction notes.", "link": null}, "plain_text": "The reading page already has four sets of public material links for PagedAttention, continuous batching, KV cache, and GPU profiling, and two of the articles include reproduction notes."}]}', 0, 0, 4, '2026-02-11T07:20:00.000Z', '2026-05-02T08:40:00.000Z'),
  ('block_notion_thesis_checklist', NULL, 'notion_thesis_checklist', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The terminology in Chapter 2 has been unified, the experiment environment table still lacks the driver version, and three conference page numbers in the references have yet to be filled in.", "link": null}, "plain_text": "The terminology in Chapter 2 has been unified, the experiment environment table still lacks the driver version, and three conference page numbers in the references have yet to be filled in."}]}', 0, 0, 5, '2026-04-19T10:35:00.000Z', '2026-05-06T11:10:00.000Z'),
  ('block_notion_interview_questions', NULL, 'notion_interview_questions', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "Last year, three system course discussions covered tail-latency metrics, on-call handover, and cross-city collaboration, and the class notes do not contain corresponding corporate conclusions.", "link": null}, "plain_text": "Last year, three system course discussions covered tail-latency metrics, on-call handover, and cross-city collaboration, and the class notes do not contain corresponding corporate conclusions."}]}', 0, 0, 6, '2025-11-12T12:05:00.000Z', '2025-11-20T13:25:00.000Z'),
  ('block_notion_public_materials', NULL, 'notion_public_materials', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The public repository includes a scheduler course project and a throughput benchmark script, and the paper abstract page only shows the research questions and experimental methods.", "link": null}, "plain_text": "The public repository includes a scheduler course project and a throughput benchmark script, and the paper abstract page only shows the research questions and experimental methods."}]}', 0, 0, 7, '2026-01-14T02:35:00.000Z', '2026-04-28T07:45:00.000Z'),
  ('block_notion_calendar_rules', NULL, 'notion_calendar_rules', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The three calls in the fall of 2025 were all scheduled outside lab meetings, with an average of twenty minutes left before the start for equipment testing; one of them was delayed by ten minutes due to network fluctuations.", "link": null}, "plain_text": "The three calls in the fall of 2025 were all scheduled outside lab meetings, with an average of twenty minutes left before the start for equipment testing; one of them was delayed by ten minutes due to network fluctuations."}]}', 0, 0, 8, '2025-12-02T09:15:00.000Z', '2025-12-02T09:55:00.000Z'),
  ('block_notion_city_compare', NULL, 'notion_city_compare', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The two short-stay records in 2025 show that the Beijing residence was about a forty-five-minute subway ride from the college, the Shanghai visiting-study dormitory was an eighteen-minute walk from the lab, and the room-charge basis differed.", "link": null}, "plain_text": "The two short-stay records in 2025 show that the Beijing residence was about a forty-five-minute subway ride from the college, the Shanghai visiting-study dormitory was an eighteen-minute walk from the lab, and the room-charge basis differed."}]}', 0, 0, 9, '2025-08-17T05:40:00.000Z', '2025-12-28T06:50:00.000Z'),
  ('block_notion_skill_evidence', NULL, 'notion_skill_evidence', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The course project uses C++ to implement the request scheduler, Python scripts handle the stress test, and Nsight recorded the memory access bottlenecks of two CUDA kernels.", "link": null}, "plain_text": "The course project uses C++ to implement the request scheduler, Python scripts handle the stress test, and Nsight recorded the memory access bottlenecks of two CUDA kernels."}]}', 0, 0, 10, '2025-09-21T04:20:00.000Z', '2026-03-16T11:40:00.000Z'),
  ('3e5a917bc06242fdb8e41a5d7903c624', NULL, '61d7e0f49a334ce8b52f8a169c4702bd', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "In the fall of 2025, two applications ended after resume review, and one completed a technical exchange; all three records were marked as historical in December of that year.", "link": null}, "plain_text": "In the fall of 2025, two applications ended after resume review, and one completed a technical exchange; all three records were marked as historical in December of that year."}]}', 0, 0, 11, '2025-12-20T08:50:00.000Z', '2026-01-03T06:20:00.000Z'),
  ('block_notion_email_drafts', NULL, 'notion_email_drafts', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "Only two unsent drafts from the previous year were retained, with subjects respectively asking about the online meeting entry and correcting the course project link.", "link": null}, "plain_text": "Only two unsent drafts from the previous year were retained, with subjects respectively asking about the online meeting entry and correcting the course project link."}]}', 0, 0, 12, '2025-10-26T07:30:00.000Z', '2025-12-06T10:15:00.000Z'),
  ('block_notion_weekly_review', NULL, 'notion_weekly_review', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The 2025 review divided information sources into the recruitment system, emails, and classmates'' retellings; the update times for the same matter once differed by four days, and the final record is based on the page snapshot at that time.", "link": null}, "plain_text": "The 2025 review divided information sources into the recruitment system, emails, and classmates'' retellings; the update times for the same matter once differed by four days, and the final record is based on the page snapshot at that time."}]}', 0, 0, 13, '2025-12-08T11:10:00.000Z', '2025-12-12T13:10:00.000Z');
