INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES
  ('block_course_fault_lab', NULL, 'notion_course_fault_lab', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The three-node experiment took 2.4 seconds to complete re-election after the leader process exited; the log loss in the second experiment came from a full disk, not a network partition.", "link": null}, "plain_text": "The three-node experiment took 2.4 seconds to complete re-election after the leader process exited; the log loss in the second experiment came from a full disk, not a network partition."}]}', 0, 0, 0, '2025-10-18T03:25:00.000Z', '2025-10-25T12:40:00.000Z'),
  ('block_open_source_issues', NULL, 'notion_open_source_issues', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The repository closed two reproduction issues this year: one caused by a missing CUDA architecture parameter, and another resolved after adding the data download checksum value to the README.", "link": null}, "plain_text": "The repository closed two reproduction issues this year: one caused by a missing CUDA architecture parameter, and another resolved after adding the data download checksum value to the README."}]}', 0, 0, 1, '2026-02-03T09:20:00.000Z', '2026-04-17T14:05:00.000Z'),
  ('block_thesis_figures', NULL, 'notion_thesis_figures', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "Figure 3 comes from the A800 test on April 18, and Figure 5 uses the public ShareGPT subset; the old Figure 7 was removed from the main text because of incorrect axis labels.", "link": null}, "plain_text": "Figure 3 comes from the A800 test on April 18, and Figure 5 uses the public ShareGPT subset; the old Figure 7 was removed from the main text because of incorrect axis labels."}]}', 0, 0, 2, '2026-03-22T06:40:00.000Z', '2026-05-04T10:50:00.000Z'),
  ('block_graduation_admin', NULL, 'notion_graduation_admin', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The degree information verification has been completed, and the library checkout status is normal; the dormitory move-out date and the place to return the graduation gown are still awaiting notice from the college.", "link": null}, "plain_text": "The degree information verification has been completed, and the library checkout status is normal; the dormitory move-out date and the place to return the graduation gown are still awaiting notice from the college."}]}', 0, 0, 3, '2026-04-08T08:30:00.000Z', '2026-05-07T11:30:00.000Z'),
  ('block_storage_reading', NULL, 'notion_storage_reading', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The reading summary compared the write amplification of LSM-tree, the point-query path of B+ trees, and object storage metadata caching, and included a classroom case of compaction stalls.", "link": null}, "plain_text": "The reading summary compared the write amplification of LSM-tree, the point-query path of B+ trees, and object storage metadata caching, and included a classroom case of compaction stalls."}]}', 0, 0, 4, '2025-09-07T02:50:00.000Z', '2026-01-19T07:20:00.000Z'),
  ('block_lab_return', NULL, 'notion_lab_return', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "The USB power meter has been handed to the equipment administrator, the A800 test account will be closed after the thesis defense, and the workstation monitor is still registered under Lin Che.", "link": null}, "plain_text": "The USB power meter has been handed to the equipment administrator, the A800 test account will be closed after the thesis defense, and the workstation monitor is still registered under Lin Che."}]}', 0, 0, 5, '2026-04-26T04:15:00.000Z', '2026-05-09T09:45:00.000Z'),
  ('block_city_visit_2025', NULL, 'notion_city_visit_2025', 'paragraph', '{"rich_text": [{"type": "text", "text": {"content": "Four weeks of accommodation for the Shanghai visiting study were settled by the school, and personal transportation expenses were 436 yuan; the return ticket to Beijing incurred a 48 yuan change fee due to rebooking.", "link": null}, "plain_text": "Four weeks of accommodation for the Shanghai visiting study were settled by the school, and personal transportation expenses were 436 yuan; the return ticket to Beijing incurred a 48 yuan change fee due to rebooking."}]}', 0, 0, 6, '2025-07-28T13:05:00.000Z', '2025-08-21T05:35:00.000Z');
